36	    /// Checks whether or not the file is ignored.
37	    /// </summary>
38	    /// <param name="fileInfo">The file information.</param>
39	    /// <param name="parent">The parent BaseItem.</param>
40	    /// <returns>True if the file should be ignored.</returns>
41	    public static bool IsIgnored(FileSystemMetadata fileInfo, BaseItem? parent)
42	    {
43	        var searchDirectory = fileInfo.IsDirectory
44	            ? new DirectoryInfo(fileInfo.FullName)
45	            : new DirectoryInfo(Path.GetDirectoryName(fileInfo.FullName) ?? string.Empty);
46	
47	        if (string.IsNullOrEmpty(searchDirectory.FullName))
48	        {
49	            return false;
50	        }
51	
52	        var ignoreFile = FindIgnoreFile(searchDirectory);
53	        if (ignoreFile is null)
54	        {
55	            return false;
56	        }
57	
58	        // Fast path in case the ignore files isn't a symlink and is empty
59	        if (ignoreFile.LinkTarget is null && ignoreFile.Length == 0)
60	        {
61	            // Ignore directory if we just have the file
62	            return true;
63	        }
64	
65	        var content = GetFileContent(ignoreFile);
66	        return string.IsNullOrWhiteSpace(content)
67	            || CheckIgnoreRules(fileInfo.FullName, content, fileInfo.IsDirectory);
68	    }
